func safeDivide(a, b int) (int, bool) {
    if b == 0 {
        return 0, false
    }
    return a / b, true
}

func main() {
    result, ok := safeDivide(10, 2)
    fmt.Println(result, ok)
    result, ok = safeDivide(1, 0)
    fmt.Println(result, ok)
}

func half(n int) (int, bool) {
    return n / 2, n % 2 == 0
}

func main() {
    h, even := half(7)
    if even {
        fmt.Println("half is", h)
    } else {
        fmt.Println(7, "is odd")
    }
}

